                    <h2 id="account-PATCHapi-v1-me-active-role">Switch role</h2>

<p>
<small class="badge badge-darkred">requires authentication</small>
</p>

<p>One account can be, for example, both an owner and a boarder (Platform
rule: role switching). Chooses which screens the app shows; only roles
the account holds are allowed.</p>

<span id="example-requests-PATCHapi-v1-me-active-role">
<blockquote>Example request:</blockquote>


<div class="bash-example">
    <pre><code class="language-bash">curl --request PATCH \
    "http://localhost:8000/api/v1/me/active-role" \
