                    <h2 id="auth-POSTapi-v1-auth-google">Continue with Google</h2>

<p>
</p>

<p>Send the ID token from Google's sign-in button. Logs in the account
linked to that Google account, or links an existing account with the
same email, or (with <code>consent: true</code>) creates a new boarder account.
Without consent, a new person gets 409 with <code>code: consent_required</code>
and nothing is created.</p>

<span id="example-requests-POSTapi-v1-auth-google">
<blockquote>Example request:</blockquote>


<div class="bash-example">
    <pre><code class="language-bash">curl --request POST \
    "http://localhost:8000/api/v1/auth/google" \
    --header "Content-Type: application/json" \
    --header "Accept: application/json" \
    --data "{
    \"id_token\": \"architecto\",
    \"consent\": true,
    \"device_name\": \"n\"
}"
</code></pre></div>


<div class="javascript-example">
    <pre><code class="language-javascript">const url = new URL(
    "http://localhost:8000/api/v1/auth/google"
);

const headers = {
    "Content-Type": "application/json",
    "Accept": "application/json",
};

let body = {
    "id_token": "architecto",
    "consent": true,
    "device_name": "n"
};

fetch(url, {
    method: "POST",
    headers,
