    "message": "b",
    "contact_phone": "-666-09",
    "room_id": 16,
    "whole": false
};

fetch(url, {
    method: "POST",
    headers,
    body: JSON.stringify(body),
}).then(response =&gt; response.json());</code></pre></div>

