                    <h2 id="bookings-GETapi-v1-applications">List applications</h2>

<p>
<small class="badge badge-darkred">requires authentication</small>
</p>

<p>For every property you can approve bookings on. Default: pending,
oldest first. <code>meta.pending_count</code> counts all pending ones.</p>

<span id="example-requests-GETapi-v1-applications">
<blockquote>Example request:</blockquote>


<div class="bash-example">
    <pre><code class="language-bash">curl --request GET \
    --get "http://localhost:8000/api/v1/applications" \
    --header "Authorization: Bearer {YOUR_AUTH_KEY}" \
    --header "Content-Type: application/json" \
    --header "Accept: application/json" \
    --data "{
    \"status\": \"approved\",
    \"property_id\": 16
}"
</code></pre></div>


