                <h1 id="dorm-finder">Dorm Finder</h1>

    

                                <h2 id="dorm-finder-GETapi-v1-listings">Search listings</h2>

<p>
</p>

<p>Published properties of verified owners, full ones too (<code>is_full</code>);
places with a free unit come first. Prices in centavos. <code>bbox</code> =
south,west,north,east (map view). <code>near</code> = lat,lng adds <code>distance_m</code>
(straight line) and allows <code>sort=nearest</code>. <code>available=1</code> hides full
places; <code>who_can_stay</code> = female or male. <code>per_page</code> up to 200 (map).</p>

<span id="example-requests-GETapi-v1-listings">
<blockquote>Example request:</blockquote>


<div class="bash-example">
    <pre><code class="language-bash">curl --request GET \
    --get "http://localhost:8000/api/v1/listings" \
    --header "Content-Type: application/json" \
    --header "Accept: application/json" \
    --data "{
    \"q\": \"b\",
    \"min_price\": 39,
    \"max_price\": 84,
    \"rental_mode\": \"whole\",
    \"who\": \"z\",
    \"available\": false,
    \"near\": \"3,14.2326\",
    \"per_page\": 79,
    \"bbox\": \"1,42.3268)))\",
    \"page\": 73
}"
</code></pre></div>


<div class="javascript-example">
    <pre><code class="language-javascript">const url = new URL(
    "http://localhost:8000/api/v1/listings"
);

const headers = {
    "Content-Type": "application/json",
    "Accept": "application/json",
};

let body = {
    "q": "b",
    "min_price": 39,
    "max_price": 84,
    "rental_mode": "whole",
    "who": "z",
    "available": false,
    "near": "3,14.2326",
    "per_page": 79,
    "bbox": "1,42.3268)))",
    "page": 73
};

fetch(url, {
