                    <h2 id="owner-PUTapi-v1-owner-profile">Update business name and payment instructions</h2>

<p>
<small class="badge badge-darkred">requires authentication</small>
</p>

<p>The GCash and bank details boarders see when they pay. Only the owner
can change them (never a caretaker).</p>

<span id="example-requests-PUTapi-v1-owner-profile">
