                    <h2 id="properties-PATCHapi-v1-properties--property_id--photos-order">Reorder photos</h2>

<p>
<small class="badge badge-darkred">requires authentication</small>
</p>

<p><code>ids</code> lists every photo of the property in the new order.</p>

<span id="example-requests-PATCHapi-v1-properties--property_id--photos-order">
<blockquote>Example request:</blockquote>


<div class="bash-example">
    <pre><code class="language-bash">curl --request PATCH \
    "http://localhost:8000/api/v1/properties/4/photos/order" \
    --header "Authorization: Bearer {YOUR_AUTH_KEY}" \
    --header "Content-Type: application/json" \
    --header "Accept: application/json" \
    --data "{
    \"ids\": [
        16
    ]
}"
</code></pre></div>


<div class="javascript-example">
    <pre><code class="language-javascript">const url = new URL(
    "http://localhost:8000/api/v1/properties/4/photos/order"
);

